query.base:
TS metrics-gcp.bigquery.otel-*
// Lowest-latency cost signal: statement_scanned_bytes_billed (DELTA, ~3 minute publish delay).
// Capacity (Editions) projects are billed for slots, not bytes, and normally report ~0 here.
| WHERE resource.attributes.gcp.resource_type == "bigquery_project"
// Stage 1: bytes billed per project per minute. DELTA amounts are additive, so SUM is exact
// across fragmented TSIDs, locations, priorities and statement types.
// `heartbeat` references query/count and job/num_in_flight, which GCP reports every minute (as 0 when idle),
// so a row exists for every published minute even when nothing was billed (billed is then null -> 0).
| STATS billed = SUM(SUM_OVER_TIME(`metrics.bigquery.googleapis.com/query/statement_scanned_bytes_billed`)),
        heartbeat = SUM(COUNT_OVER_TIME(`metrics.bigquery.googleapis.com/query/count`)) + SUM(COUNT_OVER_TIME(`metrics.bigquery.googleapis.com/job/num_in_flight`))
    BY @timestamp = TBUCKET(1 minute), resource.attributes.project_id
| EVAL billed = COALESCE(billed, 0)
// Split the 26-hour rule window into comparison periods (relative to rule execution time):
//   recent    = the last full hour, ending 5 minutes ago (skips not-yet-published minutes)
//   yesterday = the same hour 24 hours earlier (absorbs daily scheduled jobs)
//   baseline  = everything before the recent hour (hourly average)
| EVAL period = CASE(
    @timestamp >= NOW() - 65 minutes AND @timestamp < NOW() - 5 minutes, "recent",
    @timestamp >= NOW() - 5 minutes, "unpublished",
    "baseline")
| EVAL same_hour_yesterday = @timestamp >= NOW() - 1505 minutes AND @timestamp < NOW() - 1445 minutes
| STATS recent_bytes_billed = SUM(billed) WHERE period == "recent",
        baseline_bytes_billed = SUM(billed) WHERE period == "baseline",
        yesterday_bytes_billed = SUM(billed) WHERE same_hour_yesterday,
        first_seen = MIN(@timestamp),
        // heartbeat must stay referenced (here and in the WHERE below), otherwise ES|QL prunes it
        // and silently drops the minutes without billing
        published_minutes = COUNT(heartbeat)
    BY resource.attributes.project_id
